import copy
import random
from solution import solve

def reference(data):
    cache = {}
    results = []
    for i, event in enumerate(data['events']):
        now = event['t']
        cache = {k: v for k, v in cache.items() if v[1] > now}
        key = event['key']
        if event['op'] == 'put':
            cache[key] = (event['value'], now + data['ttl'], i)
            if len(cache) > data['capacity']:
                del cache[min(cache, key=lambda k: cache[k][2])]
        elif key in cache:
            value, expiry, _ = cache[key]
            results.append(value)
            cache[key] = (value, expiry, i)
        else:
            results.append(None)
    return results

rng = random.Random(17)
for trial in range(10000):
    now = -10
    events = []
    for _ in range(rng.randrange(60)):
        now += rng.randrange(4)
        event = {'op': rng.choice(['get', 'put']), 't': now, 'key': rng.choice(['', 'a', 'b', 'c', 'd'])}
        if event['op'] == 'put':
