        events.append(event)
    data = {'capacity': rng.randrange(1, 6), 'ttl': rng.randrange(8), 'events': events}
    before = copy.deepcopy(data)
    expected = reference(data)
    actual = solve(data)
    assert actual == expected, (data, expected, actual)
    assert data == before, data
print('10000 targeted randomized comparisons passed; inputs unchanged.')
